"use client";

import { MessageSquare, Plus, Github, ArrowLeft, LogOut, History } from "lucide-react";

interface SidebarProps {
  conversations: any[];
  processedRepos: {
    id: string;
    repo_url: string;
    repo_name: string;
    updated_at: string;
  }[];
  currentConversationId: string | null;
  currentRepoUrl: string;
  isRepoReady: boolean;
  userEmail: string;
  onSelectConversation: (id: string) => void;
  onSelectProcessedRepo: (url: string) => void;
  onNewChat: () => void;
  onBackToRepoSelection: () => void;
  onLogout: () => void;
}

export default function Sidebar({
  conversations,
  processedRepos,
  currentConversationId,
  currentRepoUrl,
  isRepoReady,
  userEmail,
  onSelectConversation,
  onSelectProcessedRepo,
  onNewChat,
  onBackToRepoSelection,
  onLogout,
}: SidebarProps) {
  const repoName = currentRepoUrl
    ? currentRepoUrl.split("/").slice(-2).join("/").replace(".git", "")
    : "No repository selected";

  return (
    <div className="flex w-80 flex-col border-r border-white/10 bg-slate-950/55 shadow-2xl backdrop-blur-xl">
      <div className="border-b border-white/10 p-5">
        <div className="flex items-center justify-between gap-3">
          <div>
            <p className="text-xs font-medium uppercase tracking-[0.25em] text-blue-300">
              RepoChat
            </p>
            <p className="mt-2 text-sm text-slate-400">{userEmail}</p>
          </div>
          <button
            onClick={onLogout}
            className="rounded-xl border border-white/10 p-2 text-slate-300 transition hover:bg-white/5 hover:text-white"
            aria-label="Logout"
          >
            <LogOut className="h-4 w-4" />
          </button>
        </div>

        <div className="mt-5 rounded-2xl border border-white/10 bg-white/5 p-4">
          <button
            onClick={onBackToRepoSelection}
            className="mb-3 flex items-center gap-2 text-sm text-slate-400 transition hover:text-white"
          >
            <ArrowLeft className="h-4 w-4" />
            {currentRepoUrl ? "Change Repository" : "Pick a Repository"}
          </button>
          <div className="flex items-center gap-2">
            <Github className="h-5 w-5 text-blue-400" />
            <h2 className="text-sm font-semibold text-white">Current Repo</h2>
          </div>
          <p className="mt-3 truncate rounded-xl bg-slate-900/70 px-3 py-2 font-mono text-xs text-slate-300">
            {repoName}
          </p>
        </div>
      </div>

      <div className="border-b border-white/10 p-4">
        <button
          onClick={onNewChat}
          disabled={!isRepoReady}
          className="flex w-full items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-blue-600 to-cyan-500 px-4 py-3 font-medium text-white shadow-lg shadow-blue-950/30 transition hover:brightness-110 disabled:cursor-not-allowed disabled:opacity-50"
        >
          <Plus className="h-4 w-4" />
          New Chat
        </button>
      </div>

      <div className="flex-1 overflow-y-auto">
        <div className="px-4 pt-4">
          <div className="mb-2 flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.25em] text-slate-500">
            <History className="h-3.5 w-3.5" />
            Processed Repos
          </div>
        </div>
        <div className="px-2 space-y-1">
          {processedRepos.length === 0 ? (
            <div className="px-4 py-6 text-sm text-slate-500">
              Your processed repositories will appear here.
            </div>
          ) : (
            processedRepos.map((repo) => (
              <button
                key={repo.id}
                onClick={() => onSelectProcessedRepo(repo.repo_url)}
                className={`w-full rounded-2xl border px-3 py-3 text-left transition ${
                  repo.repo_url === currentRepoUrl
                    ? "border-blue-400/40 bg-blue-500/10"
                    : "border-transparent hover:border-white/10 hover:bg-white/5"
                }`}
              >
                <p className="truncate text-sm font-medium text-white">
                  {repo.repo_name}
                </p>
                <p className="mt-1 truncate text-xs text-slate-400">
                  {repo.repo_url}
                </p>
              </button>
            ))
          )}
        </div>

        <div className="px-4 pt-6">
          <div className="mb-2 text-xs font-semibold uppercase tracking-[0.25em] text-slate-500">
            Chat Threads ({conversations.length})
          </div>
        </div>
        <div className="px-2 space-y-1 pb-4">
          {conversations.length === 0 ? (
            <div className="px-4 py-8 text-center">
              <MessageSquare className="mx-auto mb-2 h-8 w-8 text-slate-600" />
              <p className="text-sm text-slate-500">No conversations yet</p>
              <p className="mt-1 text-xs text-slate-600">
                Start chatting to create one
              </p>
            </div>
          ) : (
            conversations.map((conv, index) => (
              <button
                key={conv.conversation_id}
                onClick={() => onSelectConversation(conv.conversation_id)}
                className={`group w-full rounded-2xl border px-3 py-3 text-left transition-all duration-200 ${
                  currentConversationId === conv.conversation_id
                    ? "border-blue-500/30 bg-blue-600/20 shadow-lg"
                    : "border-transparent hover:bg-white/5"
                }`}
              >
                <div className="flex items-start gap-2">
                  <MessageSquare
                    className={`mt-0.5 h-4 w-4 flex-shrink-0 ${
                      currentConversationId === conv.conversation_id
                        ? "text-blue-400"
                        : "text-slate-500 group-hover:text-slate-400"
                    }`}
                  />
                  <div className="flex-1 min-w-0">
                    <div
                      className={`truncate text-sm font-medium ${
                        currentConversationId === conv.conversation_id
                          ? "text-white"
                          : "text-slate-300 group-hover:text-white"
                      }`}
                    >
                      {conv.title || `Chat ${conversations.length - index}`}
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-xs text-slate-500">
                        {conv.message_count} messages
                      </span>
                    </div>
                  </div>
                </div>
              </button>
            ))
          )}
        </div>
      </div>

      <div className="border-t border-white/10 p-4">
        <div className="text-center text-xs text-slate-500">
          Powered by{" "}
          <span className="font-semibold text-blue-400">Groq</span> + Local
          Embeddings
        </div>
      </div>
    </div>
  );
}