"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import Sidebar from "@/components/Sidebar";
import RepoInput from "@/components/RepoInput";
import ChatInterface from "@/components/ChatInterface";
import LoadingState from "@/components/LoadingState";
import AuthPanel, { type AuthenticatedUser } from "@/components/AuthPanel";

const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://127.0.0.1:8000";
const SESSION_STORAGE_KEY = "repochat_session_token";
const USER_STORAGE_KEY = "repochat_user";
const REMEMBER_STORAGE_KEY = "repochat_remember_me";

interface Message {
  role: "user" | "assistant";
  content: string;
  sources?: string[];
  timestamp?: string;
}

interface Conversation {
  conversation_id: string;
  title: string;
  created_at: string;
  updated_at: string;
  message_count: string;
}

interface ProcessedRepo {
  id: string;
  repo_url: string;
  repo_name: string;
  last_session_id?: string | null;
  created_at: string;
  updated_at: string;
  last_opened_at?: string | null;
}

export default function Home() {
  const [user, setUser] = useState<AuthenticatedUser | null>(null);
  const [sessionToken, setSessionToken] = useState<string | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [repoUrl, setRepoUrl] = useState("");
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [processedRepos, setProcessedRepos] = useState<ProcessedRepo[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState("");
  const [messages, setMessages] = useState<Message[]>([]);
  const [isReady, setIsReady] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    const storedToken =
      sessionStorage.getItem(SESSION_STORAGE_KEY) ||
      localStorage.getItem(SESSION_STORAGE_KEY);
    const storedUser =
      sessionStorage.getItem(USER_STORAGE_KEY) || localStorage.getItem(USER_STORAGE_KEY);

    if (storedToken && storedUser) {
      try {
        setSessionToken(storedToken);
        setUser(JSON.parse(storedUser));
      } catch {
        sessionStorage.removeItem(SESSION_STORAGE_KEY);
        sessionStorage.removeItem(USER_STORAGE_KEY);
      }
    }

    setAuthLoading(false);
  }, []);

  useEffect(() => {
    if (sessionId && isReady && sessionToken) {
      loadConversations();
      const interval = setInterval(loadConversations, 3000);
      return () => clearInterval(interval);
    }
  }, [sessionId, isReady, sessionToken]);

  useEffect(() => {
    if (user && sessionToken) {
      loadProcessedRepos();
    } else {
      setProcessedRepos([]);
    }
  }, [user, sessionToken]);

  const getAuthHeaders = () => ({
    Authorization: `Bearer ${sessionToken}`,
  });

  const handleAuthenticated = (
    nextSessionToken: string,
    nextUser: AuthenticatedUser,
    rememberMe = true
  ) => {
    if (rememberMe) {
      localStorage.setItem(SESSION_STORAGE_KEY, nextSessionToken);
      localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(nextUser));
      localStorage.setItem(REMEMBER_STORAGE_KEY, "1");
      sessionStorage.removeItem(SESSION_STORAGE_KEY);
      sessionStorage.removeItem(USER_STORAGE_KEY);
    } else {
      sessionStorage.setItem(SESSION_STORAGE_KEY, nextSessionToken);
      sessionStorage.setItem(USER_STORAGE_KEY, JSON.stringify(nextUser));
      localStorage.removeItem(SESSION_STORAGE_KEY);
      localStorage.removeItem(USER_STORAGE_KEY);
      localStorage.setItem(REMEMBER_STORAGE_KEY, "0");
    }
    setSessionToken(nextSessionToken);
    setUser(nextUser);
  };

  const handleLogout = () => {
    sessionStorage.removeItem(SESSION_STORAGE_KEY);
    sessionStorage.removeItem(USER_STORAGE_KEY);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    localStorage.removeItem(USER_STORAGE_KEY);
    localStorage.removeItem(REMEMBER_STORAGE_KEY);
    setSessionToken(null);
    setUser(null);
    setRepoUrl("");
    setSessionId(null);
    setConversationId(null);
    setConversations([]);
    setProcessedRepos([]);
    setMessages([]);
    setIsReady(false);
    setIsProcessing(false);
    setProcessingStatus("");
    setError("");
  };

  const loadProcessedRepos = async () => {
    if (!sessionToken) return;

    try {
      const res = await axios.get(`${API_URL}/api/processed-repos`, {
        headers: getAuthHeaders(),
      });
      setProcessedRepos(res.data.repos);
    } catch (err) {
      console.error("❌ Failed to load processed repos:", err);
    }
  };

  const loadConversations = async () => {
    if (!sessionId || !sessionToken) return;

    try {
      console.log("📡 Fetching conversations...");
      const res = await axios.get(`${API_URL}/api/conversations/${sessionId}`, {
        headers: getAuthHeaders(),
      });
      setConversations(res.data.conversations);
    } catch (err) {
      console.error("❌ Failed to load conversations:", err);
    }
  };

  const handleProcessRepo = async (url: string) => {
    if (!sessionToken) return;

    setRepoUrl(url);
    setSessionId(null);
    setConversationId(null);
    setConversations([]);
    setMessages([]);
    setIsReady(false);
    setIsProcessing(true);
    setError("");
    setProcessingStatus("cloning");

    try {
      console.log("🚀 Processing repo:", url);

      const res = await axios.post(
        `${API_URL}/api/process-repo`,
        {
          github_url: url,
        },
        {
          headers: getAuthHeaders(),
        }
      );

      const sid = res.data.session_id;
      console.log("✅ Session ID:", sid);

      setSessionId(sid);

      const pollInterval = setInterval(async () => {
        try {
          const statusRes = await axios.get(`${API_URL}/api/status/${sid}`, {
            headers: getAuthHeaders(),
          });
          const status = statusRes.data.status;

          console.log("📊 Status:", status);

          setProcessingStatus(status);

          if (status === "ready") {
            clearInterval(pollInterval);
            setIsProcessing(false);
            setIsReady(true);
            loadProcessedRepos();
          } else if (status === "error") {
            clearInterval(pollInterval);
            setIsProcessing(false);
            setError("Processing failed.");
          }
        } catch (err) {
          console.error("❌ Polling error:", err);
          clearInterval(pollInterval);
          setIsProcessing(false);
          setError("Polling failed.");
        }
      }, 2000);
    } catch (error: any) {
      console.error("❌ Process repo error:", error);
      setIsProcessing(false);
      setError(error?.response?.data?.detail || "Failed to process repo");
    }
  };

  const handleSendMessage = async (message: string) => {
    if (!sessionId || !sessionToken) return;

    const userMsg: Message = {
      role: "user",
      content: message,
      timestamp: new Date().toISOString(),
    };

    setMessages((prev) => [...prev, userMsg]);
    setIsSending(true);

    console.log("📨 Sending message:", message);
    console.log("👉 API:", `${API_URL}/api/chat`);

    try {
      const controller = new AbortController();

      const timeout = setTimeout(() => {
        controller.abort();
      }, 60000);

      const res = await fetch(`${API_URL}/api/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...getAuthHeaders(),
        },
        body: JSON.stringify({
          session_id: sessionId,
          message,
          conversation_id: conversationId,
        }),
        signal: controller.signal,
      });

      clearTimeout(timeout);

      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);
      }

      const newConversationId = res.headers.get("X-Conversation-ID");

      if (newConversationId && !conversationId) {
        setConversationId(newConversationId);
        setTimeout(loadConversations, 500);
      }

      const reader = res.body?.getReader();
      if (!reader) throw new Error("No stream");

      const decoder = new TextDecoder();
      let fullText = "";

      setMessages((prev) => [
        ...prev,
        { role: "assistant", content: "", timestamp: new Date().toISOString() },
      ]);

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        fullText += chunk;

        let displayText = fullText;
        let sources: string[] = [];

        const marker = "\n\n---SOURCES---\n";

        if (fullText.includes(marker)) {
          const parts = fullText.split(marker);
          displayText = parts[0];
          sources = parts[1].split("\n").filter(Boolean);
        }

        setMessages((prev) => {
          const updated = [...prev];
          updated[updated.length - 1] = {
            role: "assistant",
            content: displayText,
            sources,
            timestamp: new Date().toISOString(),
          };
          return updated;
        });
      }
    } catch (err: any) {
      console.error("❌ CHAT ERROR:", err);

      let msg = "Something went wrong.";

      if (err.name === "AbortError") {
        msg = "Request timed out.";
      } else if (err.message.includes("Failed to fetch")) {
        msg = "Backend not reachable (CORS / server down)";
      }

      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content: msg,
          timestamp: new Date().toISOString(),
        },
      ]);
    } finally {
      setIsSending(false);
    }
  };

  const handleNewChat = () => {
    setConversationId(null);
    setMessages([]);
  };

  const handleSelectConversation = async (convId: string) => {
    if (!sessionToken) return;

    try {
      const res = await axios.get(`${API_URL}/api/conversation/${convId}`, {
        headers: getAuthHeaders(),
      });
      setConversationId(convId);
      setMessages(res.data.messages);
    } catch (err) {
      console.error("❌ Load conversation error:", err);
    }
  };

  const handleSelectProcessedRepo = (selectedRepoUrl: string) => {
    if (isProcessing) return;
    handleProcessRepo(selectedRepoUrl);
  };

  const handleBackToRepoSelection = () => {
    setRepoUrl("");
    setSessionId(null);
    setConversationId(null);
    setConversations([]);
    setMessages([]);
    setIsReady(false);
    setIsProcessing(false);
    setError("");
  };

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-950 text-white">
        Loading...
      </div>
    );
  }

  if (!user) {
    return <AuthPanel onAuthenticated={handleAuthenticated} />;
  }

  return (
    <div className="flex min-h-screen bg-[radial-gradient(circle_at_top,_rgba(59,130,246,0.12),_transparent_35%),linear-gradient(180deg,#050816_0%,#0b1020_100%)] text-white">
      <Sidebar
        conversations={conversations}
        processedRepos={processedRepos}
        currentConversationId={conversationId}
        currentRepoUrl={repoUrl}
        isRepoReady={isReady}
        userEmail={user.email}
        onSelectConversation={handleSelectConversation}
        onSelectProcessedRepo={handleSelectProcessedRepo}
        onNewChat={handleNewChat}
        onBackToRepoSelection={handleBackToRepoSelection}
        onLogout={handleLogout}
      />

      <div className="flex-1 flex flex-col p-4 sm:p-6">
        {error && !isProcessing && (
          <div className="mb-4 rounded-2xl border border-rose-400/20 bg-rose-500/10 px-4 py-3 text-sm text-rose-200">
            {error}
          </div>
        )}

        {!isProcessing && !isReady && (
          <RepoInput
            onSubmit={handleProcessRepo}
            isProcessing={isProcessing}
            recentRepos={processedRepos}
            onSelectRecentRepo={handleSelectProcessedRepo}
          />
        )}

        {isProcessing && <LoadingState status={processingStatus} />}

        {isReady && sessionId && (
          <ChatInterface
            messages={messages}
            onSendMessage={handleSendMessage}
            isLoading={isSending}
            repoUrl={repoUrl}
          />
        )}
      </div>
    </div>
  );
}