"use client";

import { FormEvent, useState } from "react";
import { Mail, ShieldCheck } from "lucide-react";
import { supabase } from "@/lib/supabase";

const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://127.0.0.1:8000";

export interface AuthenticatedUser {
  user_id: string;
  email: string;
}

type AuthMode = "signin" | "signup";

interface AuthPanelProps {
  prefilledEmail?: string | null;
  onAuthenticated: (
    sessionToken: string,
    user: AuthenticatedUser,
    rememberMe?: boolean
  ) => void;
}

export default function AuthPanel({
  prefilledEmail,
  onAuthenticated,
}: AuthPanelProps) {
  const [mode, setMode] = useState<AuthMode>("signin");
  const [email, setEmail] = useState(prefilledEmail ?? "");
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(true);
  const [otp, setOtp] = useState("");
  const [otpStep, setOtpStep] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const clearFeedback = () => {
    setError("");
    setMessage("");
  };

  const parseError = (err: unknown, fallback: string) => {
    if (err instanceof TypeError) {
      return `Cannot reach auth service at ${API_URL}. Make sure backend is running and NEXT_PUBLIC_API_URL is correct.`;
    }
    if (err instanceof Error) {
      return err.message;
    }
    return fallback;
  };

  const exchangeSupabaseToken = async (accessToken: string, keepSignedIn = true) => {
    const exchangeRes = await fetch(`${API_URL}/api/auth/exchange-supabase`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ access_token: accessToken }),
    });
    const exchangePayload = await exchangeRes.json().catch(() => ({}));
    if (!exchangeRes.ok) {
      throw new Error(exchangePayload.detail || "Authentication exchange failed");
    }
    onAuthenticated(exchangePayload.session_token, exchangePayload.user, keepSignedIn);
  };

  const handleSignInRequestOtp = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    clearFeedback();
    setLoading(true);

    try {
      const res = await fetch(`${API_URL}/api/auth/signin/request-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      const payload = await res.json().catch(() => ({}));
      if (!res.ok) {
        throw new Error(payload.detail || "Failed to send OTP");
      }

      setOtpStep(true);
      setMessage(
        payload.debug_otp
          ? `Two-factor code sent. Dev OTP: ${payload.debug_otp}`
          : "Two-factor code sent to your email."
      );
    } catch (err: unknown) {
      setError(parseError(err, "Failed to start sign-in"));
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    clearFeedback();
    setLoading(true);

    try {
      const { error: oauthError } = await supabase.auth.signInWithOAuth({
        provider: "google",
        options: {
          redirectTo: `${window.location.origin}/auth/v1/callback`,
        },
      });
      if (oauthError) throw oauthError;
    } catch (err: unknown) {
      setError(parseError(err, "Google sign-in failed"));
      setLoading(false);
    }
  };

  const handleCreateAccount = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    clearFeedback();
    setLoading(true);

    try {
      const { data, error: signUpError } = await supabase.auth.signUp({
        email: email.trim(),
        password,
      });

      if (signUpError) {
        const msg = signUpError.message.toLowerCase();
        if (msg.includes("already") || msg.includes("registered") || msg.includes("exists")) {
          throw new Error("User already exists. Please sign in instead.");
        }
        throw signUpError;
      }
      if (data.user && Array.isArray(data.user.identities) && data.user.identities.length === 0) {
        throw new Error("User already exists. Please sign in instead.");
      }

      const accessToken = data.session?.access_token;
      if (!accessToken) {
        setMessage("Account created. Please verify your email, then sign in.");
        return;
      }

      await exchangeSupabaseToken(accessToken, rememberMe);
      await supabase.auth.signOut();
    } catch (err: unknown) {
      setError(parseError(err, "Failed to create account"));
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    clearFeedback();
    setLoading(true);

    try {
      const res = await fetch(`${API_URL}/api/auth/verify-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, otp }),
      });

      const payload = await res.json().catch(() => ({}));
      if (!res.ok) {
        throw new Error(payload.detail || "OTP verification failed");
      }

      onAuthenticated(payload.session_token, payload.user, rememberMe);
    } catch (err: unknown) {
      setError(parseError(err, "OTP verification failed"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[radial-gradient(circle_at_top,_rgba(59,130,246,0.22),_transparent_35%),linear-gradient(180deg,#050816_0%,#0b1020_50%,#050816_100%)] text-white">
      <div className="mx-auto flex min-h-screen max-w-6xl items-center justify-center px-4 py-10">
        <div className="grid w-full max-w-5xl overflow-hidden rounded-3xl border border-white/10 bg-white/5 shadow-2xl backdrop-blur-xl md:grid-cols-[1.1fr_0.9fr]">
          <div className="hidden border-r border-white/10 bg-gradient-to-br from-blue-600/20 via-cyan-500/10 to-transparent p-10 md:block">
            <div className="max-w-md">
              <p className="rounded-full border border-blue-400/30 bg-blue-400/10 px-3 py-1 text-xs font-medium uppercase tracking-[0.25em] text-blue-200">
                RepoChat
              </p>
              <h1 className="mt-6 text-4xl font-semibold leading-tight">
                {mode === "signup" ? "Create your RepoChat account" : "Sign in to RepoChat"}
              </h1>
              <p className="mt-4 text-sm leading-7 text-slate-300">
                Use email OTP or Google to access your repo workspace.
              </p>
            </div>
          </div>

          <div className="p-6 sm:p-8 md:p-10">
            <div className="mx-auto max-w-md">
              <div className="mb-8 md:hidden">
                <p className="text-xs font-medium uppercase tracking-[0.25em] text-blue-300">
                  RepoChat
                </p>
                <h1 className="mt-3 text-3xl font-semibold">
                  {mode === "signup" ? "Create account" : "Sign in"}
                </h1>
              </div>

              <div className="rounded-3xl border border-white/10 bg-slate-950/60 p-6 shadow-xl">
                <div className="flex gap-2 rounded-2xl border border-white/10 bg-white/5 p-1">
                  <button
                    type="button"
                    onClick={() => {
                      setMode("signin");
                      setOtpStep(false);
                      setOtp("");
                      setPassword("");
                      clearFeedback();
                    }}
                    className={`flex-1 rounded-2xl px-3 py-2 text-sm font-medium transition ${
                      mode === "signin"
                        ? "bg-blue-500/15 text-white"
                        : "text-slate-300 hover:bg-white/5"
                    }`}
                  >
                    Sign in
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      setMode("signup");
                      setOtpStep(false);
                      setOtp("");
                      setPassword("");
                      clearFeedback();
                    }}
                    className={`flex-1 rounded-2xl px-3 py-2 text-sm font-medium transition ${
                      mode === "signup"
                        ? "bg-blue-500/15 text-white"
                        : "text-slate-300 hover:bg-white/5"
                    }`}
                  >
                    Create account
                  </button>
                </div>

                <div className="flex items-center gap-3">
                  <div className="rounded-2xl bg-blue-500/15 p-3 text-blue-300">
                    {otpStep ? <ShieldCheck className="h-6 w-6" /> : <Mail className="h-6 w-6" />}
                  </div>
                  <div>
                    <h2 className="text-2xl font-semibold">
                      {otpStep ? "Enter verification code" : mode === "signup" ? "Create account" : "Sign in"}
                    </h2>
                    <p className="mt-1 text-sm text-slate-400">
                      {otpStep
                        ? "Use the 6-digit code from your email."
                        : mode === "signup"
                        ? "Use your email and create a password."
                        : "Enter your email and password, then verify OTP for two-factor authentication."}
                    </p>
                  </div>
                </div>

                {error && <p className="mt-4 text-sm text-rose-300">{error}</p>}
                {message && <p className="mt-4 text-sm text-emerald-300">{message}</p>}

                {!otpStep ? (
                  <form
                    className="mt-6 space-y-4"
                    onSubmit={mode === "signin" ? handleSignInRequestOtp : handleCreateAccount}
                  >
                    <label className="block text-sm text-slate-300">
                      Email
                      <input
                        type="email"
                        required
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="you@example.com"
                        className="mt-2 w-full rounded-2xl border border-white/10 bg-slate-900/80 px-4 py-3 text-sm outline-none transition focus:border-blue-400"
                      />
                    </label>

                    <label className="block text-sm text-slate-300">
                      Password
                      <input
                        type="password"
                        required
                        minLength={6}
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder={mode === "signup" ? "Create a password" : "Enter your password"}
                        className="mt-2 w-full rounded-2xl border border-white/10 bg-slate-900/80 px-4 py-3 text-sm outline-none transition focus:border-blue-400"
                      />
                    </label>

                    <label className="flex items-center gap-2 text-sm text-slate-300">
                      <input
                        type="checkbox"
                        checked={rememberMe}
                        onChange={(e) => setRememberMe(e.target.checked)}
                        className="h-4 w-4 rounded border-white/20 bg-slate-900"
                      />
                      Remember me
                    </label>

                    <button
                      type="submit"
                      disabled={loading || !email.trim() || password.length < 6}
                      className="w-full rounded-2xl bg-gradient-to-r from-blue-600 to-cyan-500 px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-900/30 transition hover:brightness-110 disabled:opacity-50"
                    >
                      {loading
                        ? mode === "signin"
                          ? "Checking credentials..."
                          : "Creating account..."
                        : mode === "signin"
                        ? "Sign in and send OTP"
                        : "Create account"}
                    </button>
                  </form>
                ) : (
                  <form className="mt-6 space-y-4" onSubmit={handleVerifyOtp}>
                    <label className="block text-sm text-slate-300">
                      Email
                      <input
                        type="email"
                        required
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className="mt-2 w-full rounded-2xl border border-white/10 bg-slate-900/80 px-4 py-3 text-sm outline-none transition focus:border-blue-400"
                      />
                    </label>

                    <label className="block text-sm text-slate-300">
                      6-digit OTP
                      <input
                        type="text"
                        inputMode="numeric"
                        pattern="\d{6}"
                        maxLength={6}
                        required
                        value={otp}
                        onChange={(e) =>
                          setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))
                        }
                        placeholder="123456"
                        className="mt-2 w-full rounded-2xl border border-white/10 bg-slate-900/80 px-4 py-3 text-sm tracking-[0.35em] outline-none transition focus:border-blue-400"
                      />
                    </label>

                    <button
                      type="submit"
                      disabled={loading || otp.length !== 6}
                      className="w-full rounded-2xl bg-gradient-to-r from-blue-600 to-cyan-500 px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-900/30 transition hover:brightness-110 disabled:opacity-50"
                    >
                      {loading ? "Verifying..." : "Verify OTP"}
                    </button>

                    <button
                      type="button"
                      onClick={() => {
                        setOtpStep(false);
                        setOtp("");
                        clearFeedback();
                      }}
                      className="w-full rounded-2xl border border-white/10 px-4 py-3 text-sm text-slate-300 transition hover:bg-white/5"
                    >
                      Back to sign in
                    </button>
                  </form>
                )}

                <div className="mt-6">
                  <div className="relative my-5">
                    <div className="absolute inset-0 flex items-center">
                      <div className="w-full border-t border-white/10" />
                    </div>
                    <div className="relative flex justify-center">
                      <span className="bg-slate-950/60 px-3 text-xs uppercase tracking-[0.25em] text-slate-500">
                        or
                      </span>
                    </div>
                  </div>

                  <button
                    type="button"
                    onClick={handleGoogleSignIn}
                    disabled={loading}
                    className="w-full rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-sm font-semibold text-slate-200 transition hover:bg-white/10 disabled:opacity-50"
                  >
                    Continue with Google
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}